Method.Implementation:
set tSC=##super(pRequest,.pResponse)
if $$$ISOK(tSC){
	// If file exists rename it to new name
	set tFilePath=##class(Ens.Util.File).fixPath(..Adapter.FilePath)
	set tRenameFilePath=##class(Ens.Util.File).fixPath(..TargetFilePath)
	Set tFilename=tFilePath_##class(Ens.Util.File).CreateTimestamp(##class(%File).GetFilename(pRequest.OriginalFilename),..Filename)
	set tCopyFileName=tRenameFilePath_##class(Ens.Util.File).CreateTimestamp(##class(%File).GetFilename(pRequest.OriginalFilename),..RenameToFileName)
	if ##class(%File).Exists(tFilename){
		set tSC=##class(%File).Rename(tFilename,tCopyFileName)
		if (tSC=0){
			set tSC=$$$ERROR($$$FileCanNotCopy," RenFileame from  "_tFilename_" to "_tCopyFileName_" failed.")
		}
	}
}
Quit tSC

Try {
	do {
		set tStatus = $$$OK
		set tStatus=##super()
	    If $$$ISERR(tStatus) Quit
		Set tFilePath=..Adapter.fixPath(..Adapter.FilePath)
		// Check if Directory is present if not create
		 If (##class(%File).DirectoryExists(tFilePath)=0) {
			set tStatus=##class(%File).CreateDirectoryChain(tFilePath)
			$$$TRACE( " Directrory Create Status "_tStatus)
			if (tStatus=0){
				set tStatus=$$$ERROR($$$DirectoryNotExist," Filepath specified in setting does not Exists. Failed to Create Directory "_tFilePath)
				quit
			}
		}
		// Check if Target Directory is present if not Create it
		Set tFilePath=..Adapter.fixPath(..TargetFilePath)
		If (##class(%File).DirectoryExists(tFilePath)=0) {
			set tStatus=##class(%File).CreateDirectoryChain(tFilePath)
			$$$TRACE( " Directrory Create Status "_tStatus)
			if (tStatus=0){
				set tStatus=$$$ERROR($$$DirectoryNotExist," Target directory specified in setting  does not Exists. Failed to Create Directory "_tFilePath)
				quit
			}
		}

	}while(0)
}
Catch ex {
	Set tStatus = $$$EnsSystemError
}
Quit tStatus
